'use strict';const fs=require('fs'),crypto=require('crypto');const {chromium}=require('/workspace/gridex-krypkorning-run-20261111/node_modules/playwright');const root='/workspace/gridex-site-price-evidence-20261112',prev='/workspace/gridex-scenario-native-evidence-20261112';const actors=JSON.parse(fs.readFileSync(prev+'/actors.private.json','utf8')),keys=JSON.parse(fs.readFileSync(prev+'/runtime-renewed.private.json','utf8'));const base='http://127.0.0.1:3108',api='http://127.0.0.1:55321',company='b36f6a30-18cd-4a70-8652-5b2da9b4eb64',customer='33fd349e-a3c9-4647-8ce3-b32eec9099a0';const tag=crypto.randomBytes(4).toString('hex'),sha=x=>crypto.createHash('sha256').update(x).digest('hex');const stable=x=>JSON.stringify(x,Object.keys(x).sort());const result={scenarioId:'SITE01.04',scope:'NORMAL_MANUAL_UI_UNVERIFIED_PRICE_HINT_ISOLATION_NOT_MARKET_AREA_OR_INVOICE_ACCEPTANCE',sourceReceipt:'source-with-dashboard.safe.json',actors:[],steps:[],newSites:[],noProviderWorkerStarted:true};const save=()=>fs.writeFileSync(root+'/site-ui-original.safe.json',JSON.stringify(result,null,2),{mode:0o600});
async function rows(){const r=await fetch(api+'/rest/v1/customer_sites?company_id=eq.'+company+'&customer_id=eq.'+customer+'&select=*',{headers:{apikey:keys.serviceRoleKey,Authorization:'Bearer '+keys.serviceRoleKey}});if(!r.ok)throw Error('READ_ONLY_SITE_READBACK_FAILED');return await r.json()}
function project(s){return{id:s.id,company_id:s.company_id,customer_id:s.customer_id,site_name:s.site_name,facility_id:s.facility_id,status:s.status,is_active:s.is_active,address_hash:s.address_hash,address_status:s.address_status,facility_data_status:s.facility_data_status,resolution_status:s.resolution_status,grid_owner_id:s.grid_owner_id,price_area_code:s.price_area_code,metadata:s.metadata}}
function checkSecrets(body){const values=[keys.serviceRoleKey,keys.jwtSecret,...actors.map(a=>a.password)];if(values.some(s=>body.includes(s)))throw Error('KNOWN_SECRET_PRESENT_IN_RESPONSE')}
let browser;let currentContext,currentPage;
async function logout(a){if(!currentPage)return;await currentPage.goto(base+'/logout',{waitUntil:'domcontentloaded',timeout:60000});await Promise.all([currentPage.waitForURL(u=>u.pathname==='/login',{timeout:60000}),currentPage.locator('form[action="/logout"] button[type=submit]').click()]);a.normalUiPostLogout=true;await currentContext.close();currentContext=currentPage=null;save()}
async function login(a){currentContext=await browser.newContext();currentPage=await currentContext.newPage();await currentPage.goto(base+'/login',{waitUntil:'domcontentloaded',timeout:180000});await currentPage.locator('input[name=email]').fill(a.email);await currentPage.locator('input[name=password]').fill(a.password);await Promise.all([currentPage.waitForURL(u=>u.pathname!='/login',{timeout:120000}),currentPage.locator('button[type=submit]').click()]);const body=await currentPage.content();checkSecrets(body);const p={label:a.label,normalUiLogin:true,path:new URL(currentPage.url()).pathname,platformHeadingPresent:body.includes('Plattformsöversikt')&&body.includes('Gridex Platform Operations'),companyHeadingPresent:body.includes('Bolagsyta')};result.actors.push(p);save();return p}
async function openForm(editId){const url=base+'/admin/customers/'+customer+(editId?'?editSite='+editId:'?tab=sites');const r=await currentPage.goto(url,{waitUntil:'domcontentloaded',timeout:180000});const body=await currentPage.content();checkSecrets(body);const form=currentPage.locator('form').filter({has:currentPage.locator('input[name=site_name]')});result.steps.push({kind:'NORMAL_CUSTOMER_PAGE',editId:editId??null,status:r.status(),path:new URL(currentPage.url()).pathname,siteForms:await form.count(),bodySha256:sha(body)});save();if(r.status()!==200||await form.count()!==1)throw Error('BLOCKED_NORMAL_UI_SITE_FORM');const details=form.locator('xpath=ancestor::details[1]');if(await details.count()&&!await details.getAttribute('open'))await details.locator('summary').click();const options=await form.locator('select[name=price_area_code] option').evaluateAll(ns=>ns.map(n=>n.value));if(!['SE3','SE4'].every(v=>options.includes(v)))throw Error('BLOCKED_NORMAL_PRICEAREA_OPTIONS');result.availablePriceAreaOptions=options;return form}
async function fill(form,v){for(const[k,value]of Object.entries({site_name:v.name,facility_id:v.facility,street:v.street,postal_code:v.postal,city:v.city,country:'SE'}))await form.locator('[name='+k+']').fill(value);await form.locator('[name=status]').selectOption('draft');await form.locator('[name=site_flow_type]').selectOption('switch');await form.locator('[name=price_area_code]').selectOption(v.area)}
async function submit(form,label){const [r]=await Promise.all([currentPage.waitForResponse(r=>r.request().method()==='POST'&&new URL(r.url()).pathname==='/admin/customers/'+customer,{timeout:120000}),form.locator('button[type=submit]').click()]);const body=await r.text();checkSecrets(body);result.steps.push({kind:'NORMAL_SERVER_ACTION_POST',label,status:r.status(),bodySha256:sha(body),bodyBytes:Buffer.byteLength(body)});save();await form.locator('button[type=submit]').waitFor({state:'visible',timeout:30000});return r.status()}
(async()=>{try{browser=await chromium.launch({executablePath:'/usr/bin/chromium',args:['--no-sandbox']});const before=await rows();const beforeHashes=Object.fromEntries(before.map(r=>[r.id,sha(stable(r))]));result.beforeSites=before.map(s=>({id:s.id,rowSha256:beforeHashes[s.id]}));const admin=await login(actors.find(a=>a.label==='bootstrap_platform_admin'));if(!admin.platformHeadingPresent)throw Error('DASHBOARD_PLATFORM_PERSONA_NOT_REACHED');const cases=[{name:'Kryp SITE01.04 SE3 '+tag,area:'SE3',facility:'735999999990000031',street:'Simuleringsgatan 31',postal:'11122',city:'Stockholm'},{name:'Kryp SITE01.04 SE4 '+tag,area:'SE4',facility:'735999999990000048',street:'Simuleringsgatan 41',postal:'21122',city:'Malmö'}];for(const v of cases){const f=await openForm();await fill(f,v);await submit(f,'CREATE_'+v.area);const after=await rows();const own=after.filter(s=>s.site_name===v.name);if(own.length!==1)throw Error('CREATE_NOT_CONFIRMED_EXACTLY_ONE_SITE');const s=project(own[0]);result.newSites.push(s);save();if(s.price_area_code!==null||s.grid_owner_id!==null)throw Error('MANUAL_HINT_BECAME_OPERATIONAL_FIELDS');const hint=s.metadata?.address_candidate_metadata?.manual_price_area_hint;if(hint!==v.area)throw Error('MANUAL_HINT_NOT_PRESERVED');if(s.address_status==='verified'||s.facility_data_status==='verified')throw Error('UNTRUSTED_HINT_VERIFIED');if(!before.every(r=>after.find(s=>s.id===r.id)&&sha(stable(after.find(s=>s.id===r.id)))===beforeHashes[r.id]))throw Error('PREEXISTING_SITE_CHANGED')}
const [one,two]=result.newSites;result.distinctSiteAndAddressHashes=one.id!==two.id&&one.address_hash!==two.address_hash;const preEdit=await rows();const secondHash=sha(stable(preEdit.find(s=>s.id===two.id)));let f=await openForm(one.id);await fill(f,cases[0]);await submit(f,'EDIT_ID_BOUND_SAME_INPUT_REPLAY');let after=await rows();result.editReplay={sameSiteId:after.some(s=>s.id===one.id),countBefore:preEdit.length,countAfter:after.length,secondSiteUnchanged:sha(stable(after.find(s=>s.id===two.id)))===secondHash};save();if(result.availablePriceAreaOptions.includes('SE1')){f=await openForm(one.id);await fill(f,{...cases[0],area:'SE1'});await submit(f,'EDIT_ONLY_FIRST_HINT_TO_SE1');after=await rows();result.singleSiteChange={first:project(after.find(s=>s.id===one.id)),secondUnchanged:sha(stable(after.find(s=>s.id===two.id)))===secondHash}}result.finalSiteRows=after.map(project);result.state='SITE_UI_TERMINAL';await logout(admin);const owner=await login(actors.find(a=>a.label==='ordinary_tenant_owner'));await logout(owner);result.dashboardPersonaOracle=admin.platformHeadingPresent&&!owner.platformHeadingPresent&&owner.companyHeadingPresent;result.state='TERMINAL';save()}catch(e){result.state='CAPTURE_STOPPED_AT_REAL_BOUNDARY';result.safeErrorCode=String(e.message||e.name).startsWith('BLOCKED_')||String(e.message).match(/^[A-Z_]+$/)?e.message:e.name;save();if(currentPage){try{await logout(result.actors.at(-1))}catch{result.normalLogoutCleanupFailed=true;save()}}process.exitCode=1}finally{if(browser&&!result.actors.some(a=>a.label==='ordinary_tenant_owner')){try{const o=await login(actors.find(a=>a.label==='ordinary_tenant_owner'));await logout(o);result.dashboardPersonaOracle=Boolean(result.actors.find(a=>a.label==='bootstrap_platform_admin')?.platformHeadingPresent)&&!o.platformHeadingPresent&&o.companyHeadingPresent;save()}catch(e){result.ownerPersonaCaptureError=e.name;save()}}await browser?.close()}})();

